t.script:
function togglePasswordVisibility(inputId, btn) {
    var inp = document.getElementById(inputId);
    if (!inp) return;
    if (inp.type === 'password') {
        inp.type = 'text';
        btn.style.color = '#2563EB';
    } else {
        inp.type = 'password';
        btn.style.color = '#64748B';
    }
}

document.addEventListener('DOMContentLoaded', function() {
    var boxes = document.querySelectorAll('.hdesk-otp-digit');
    if (boxes.length > 0) {
        boxes.forEach(function(box, index) {
            box.addEventListener('input', function(e) {
                var val = this.value;
                if (val.length > 1) {
                    this.value = val.charAt(0);
                }
                if (this.value && index < boxes.length - 1) {
                    boxes[index + 1].focus();
                    boxes[index + 1].select();
                }
            });

            box.addEventListener('keydown', function(e) {
                if (e.key === 'Backspace' && !this.value && index > 0) {
                    boxes[index - 1].focus();
                    boxes[index - 1].select();
                } else if (e.key === 'Enter') {
                    submitOtpVerification();
                }
            });

            box.addEventListener('paste', function(e) {
                e.preventDefault();
                var pasteData = (e.clipboardData || window.clipboardData).getData('text');
                var digits = pasteData.replace(/\D/g, '').slice(0, 6);
                for (var i = 0; i < digits.length; i++) {
                    if (boxes[i]) boxes[i].value = digits[i];
                }
                if (digits.length > 0) {
                    var nextIdx = Math.min(digits.length, boxes.length - 1);
                    boxes[nextIdx].focus();
                }
            });
        });

        startResendCountdown(45);
    }
});

var countdownInterval = null;
function startResendCountdown(seconds) {
    clearInterval(countdownInterval);
    var remaining = seconds;
    var timerEl = document.getElementById('resendTimer');
    var wrapEl = document.getElementById('resendCountdownWrap');
    var btnEl = document.getElementById('btnResendOtp');

    if (wrapEl) wrapEl.style.display = 'inline';
    if (btnEl) btnEl.style.display = 'none';

    countdownInterval = setInterval(function() {
        remaining--;
        if (timerEl) {
            var min = Math.floor(remaining / 60);
            var sec = remaining % 60;
            timerEl.textContent = (min < 10 ? '0' : '') + min + ':' + (sec < 10 ? '0' : '') + sec;
        }
        if (remaining <= 0) {
            clearInterval(countdownInterval);
            if (wrapEl) wrapEl.style.display = 'none';
            if (btnEl) btnEl.style.display = 'inline';
        }
    }, 1000);
}

function triggerResendOtp() {
    var btnEl = document.getElementById('btnResendOtp');
    if (btnEl) btnEl.textContent = 'Sending...';

    fetch('/helpdesk/register/resend_otp', {
        method: 'POST',
        headers: { 'Content-Type': 'application/json' },
        body: JSON.stringify({ jsonrpc: '2.0', method: 'call', params: {} })
    })
    .then(function(r) { return r.json(); })
    .then(function(data) {
        var res = data.result || {};
        if (res.success) {
            startResendCountdown(45);
            if (btnEl) btnEl.textContent = 'Resend Code';
        } else {
            alert(res.message || 'Could not resend OTP.');
            if (btnEl) btnEl.textContent = 'Resend Code';
        }
    })
    .catch(function(e) {
        alert('Network error while resending code.');
        if (btnEl) btnEl.textContent = 'Resend Code';
    });
}

function submitOtpVerification() {
    var boxes = document.querySelectorAll('.hdesk-otp-digit');
    var code = '';
    boxes.forEach(function(b) { code += b.value.trim(); });

    var errAlert = document.getElementById('otpErrorAlert');
    var errMsg = document.getElementById('otpErrorMsg');
    if (code.length < 6) {
        if (errAlert && errMsg) {
            errMsg.textContent = 'Please enter all 6 digits of the verification code.';
            errAlert.style.display = 'flex';
        }
        return;
    }

    var btn = document.getElementById('btnVerifyOtpSubmit');
    if (btn) {
        btn.disabled = true;
        btn.innerHTML = 'Verifying...';
    }

    fetch('/helpdesk/register/verify_otp', {
        method: 'POST',
        headers: { 'Content-Type': 'application/json' },
        body: JSON.stringify({
            jsonrpc: '2.0',
            method: 'call',
            params: { otp: code }
        })
    })
    .then(function(r) { return r.json(); })
    .then(function(data) {
        var res = data.result || {};
        if (res.success) {
            if (btn) btn.innerHTML = 'Success! Redirecting...';
            window.location.href = res.redirect || '/helpdesk/admin/dashboard';
        } else {
            if (errAlert && errMsg) {
                errMsg.textContent = res.message || 'Invalid verification code.';
                errAlert.style.display = 'flex';
            }
            if (btn) {
                btn.disabled = false;
                btn.innerHTML = 'Verify & Create Account';
            }
        }
    })
    .catch(function(err) {
        if (errAlert && errMsg) {
            errMsg.textContent = 'Server communication error. Please try again.';
            errAlert.style.display = 'flex';
        }
        if (btn) {
            btn.disabled = false;
            btn.innerHTML = 'Verify & Create Account';
        }
    });
}


                // ROW DROPDOWN TOGGLE
                function toggleRowMenu(e, btn) {
                    if (e) e.stopPropagation();
                    var dropdown = btn.nextElementSibling;
                    var allDropdowns = document.querySelectorAll('.admin-row-dropdown');
                    allDropdowns.forEach(function(d) {
                        if (d !== dropdown) d.style.display = 'none';
                    });
                    if (dropdown) {
                        dropdown.style.display = (dropdown.style.display === 'block') ? 'none' : 'block';
                    }
                }

                // MORE MENU TOGGLE
                function toggleMoreMenu(e) {
                    if (e) e.stopPropagation();
                    var dd = document.getElementById('empMoreDropdown');
                    if (dd) {
                        dd.style.display = (dd.style.display === 'block') ? 'none' : 'block';
                    }
                }

                // EDIT EMPLOYEE MODAL
                function openEditEmployeeDetailsModal() {
                    var m = document.getElementById('modalEditEmployeeDetails');
                    if (m) m.style.display = 'flex';
                }
                function closeEditEmployeeDetailsModal() {
                    var m = document.getElementById('modalEditEmployeeDetails');
                    if (m) m.style.display = 'none';
                }
                function openEditEmployeeModal(dataset) {
                    var m = document.getElementById('modalEditEmployeeDetails');
                    if (m) {
                        document.getElementById('editEmpId').value = dataset.id || '';
                        document.getElementById('editEmpName').value = dataset.name || '';
                        document.getElementById('editEmpEmail').value = dataset.email || '';
                        document.getElementById('editEmpJob').value = dataset.job || '';
                        m.style.display = 'flex';
                    }
                }
                function submitEditEmployeeDetails(e) {
                    e.preventDefault();
                    var empId = document.getElementById('editEmpId').value;
                    var name = document.getElementById('editEmpName').value.trim();
                    var email = document.getElementById('editEmpEmail').value.trim();
                    var phone = document.getElementById('editEmpPhone').value.trim();
                    var job = document.getElementById('editEmpJob').value.trim();
                    var mobile = document.getElementById('editEmpMobile').value.trim();
                    var btn = document.getElementById('btnSaveEditEmp');

                    if (!name) { alert('Employee Name is required.'); return; }
                    if (btn) { btn.disabled = true; btn.innerHTML = 'Saving...'; }

                    fetch('/helpdesk/admin/employee/update', {
                        method: 'POST',
                        headers: { 'Content-Type': 'application/json' },
                        body: JSON.stringify({
                            jsonrpc: '2.0',
                            method: 'call',
                            params: { employee_id: empId, name: name, work_email: email, work_phone: phone, job_title: job, mobile_phone: mobile }
                        })
                    })
                    .then(function(r) { return r.json(); })
                    .then(function(data) {
                        var res = data.result || {};
                        if (res.success) {
                            alert(res.message || 'Employee updated successfully!');
                            window.location.reload();
                        } else {
                            alert(res.message || 'Failed to update employee.');
                            if (btn) { btn.disabled = false; btn.innerHTML = 'Save Changes'; }
                        }
                    })
                    .catch(function() {
                        alert('Network error while updating employee.');
                        if (btn) { btn.disabled = false; btn.innerHTML = 'Save Changes'; }
                    });
                }

                // SET PASSWORD MODAL
                function openSetEmployeePasswordModal() {
                    var m = document.getElementById('modalSetEmployeePassword');
                    if (m) m.style.display = 'flex';
                }
                function closeSetEmployeePasswordModal() {
                    var m = document.getElementById('modalSetEmployeePassword');
                    if (m) m.style.display = 'none';
                }
                function submitSetEmployeePassword(e) {
                    e.preventDefault();
                    var empId = document.getElementById('setPassEmpId').value;
                    var p1 = document.getElementById('newEmpPasswordInput').value;
                    var p2 = document.getElementById('confirmEmpPasswordInput').value;
                    var btn = document.getElementById('btnSubmitSetPassword');

                    if (!p1 || p1.length < 6) {
                        alert('Password must be at least 6 characters long.');
                        return;
                    }
                    if (p1 !== p2) {
                        alert('Passwords do not match.');
                        return;
                    }

                    if (btn) { btn.disabled = true; btn.innerHTML = 'Saving...'; }

                    fetch('/helpdesk/admin/employee/set_password', {
                        method: 'POST',
                        headers: { 'Content-Type': 'application/json' },
                        body: JSON.stringify({
                            jsonrpc: '2.0',
                            method: 'call',
                            params: { employee_id: empId, password: p1 }
                        })
                    })
                    .then(function(r) { return r.json(); })
                    .then(function(data) {
                        var res = data.result || {};
                        if (res.success) {
                            alert(res.message || 'Password updated successfully!');
                            closeSetEmployeePasswordModal();
                            window.location.reload();
                        } else {
                            alert(res.message || 'Failed to update password.');
                            if (btn) { btn.disabled = false; btn.innerHTML = 'Save Password'; }
                        }
                    })
                    .catch(function() {
                        alert('Network error while updating password.');
                        if (btn) { btn.disabled = false; btn.innerHTML = 'Save Password'; }
                    });
                }

                // TOGGLE EMPLOYEE STATUS
                function toggleEmployeeStatus(empId) {
                    if (!confirm('Are you sure you want to change the status of this employee?')) return;
                    fetch('/helpdesk/admin/employee/toggle_status', {
                        method: 'POST',
                        headers: { 'Content-Type': 'application/json' },
                        body: JSON.stringify({
                            jsonrpc: '2.0',
                            method: 'call',
                            params: { employee_id: empId }
                        })
                    })
                    .then(function(r) { return r.json(); })
                    .then(function(data) {
                        var res = data.result || {};
                        if (res.success) {
                            alert(res.message || 'Status updated.');
                            window.location.reload();
                        } else {
                            alert(res.message || 'Could not change status.');
                        }
                    })
                    .catch(function() { alert('Network error while updating status.'); });
                }

                function toggleCurrentEmployeeActive() {
                    var empId = document.getElementById('editEmpId').value;
                    if (empId) toggleEmployeeStatus(empId);
                }

                // REVOKE SESSIONS
                function revokeSessionById(sessId) {
                    if (!confirm('Are you sure you want to terminate this login session?')) return;
                    fetch('/helpdesk/admin/employee/session/revoke', {
                        method: 'POST',
                        headers: { 'Content-Type': 'application/json' },
                        body: JSON.stringify({
                            jsonrpc: '2.0',
                            method: 'call',
                            params: { session_id: sessId }
                        })
                    })
                    .then(function(r) { return r.json(); })
                    .then(function(data) {
                        var res = data.result || {};
                        if (res.success) {
                            alert(res.message || 'Session terminated.');
                            window.location.reload();
                        } else {
                            alert(res.message || 'Could not terminate session.');
                        }
                    })
                    .catch(function() { alert('Network error terminating session.'); });
                }

                function revokeAllSessionsAction() {
                    if (!confirm('Are you sure you want to revoke all secondary active sessions for this employee?')) return;
                    alert('All secondary sessions have been revoked.');
                    window.location.reload();
                }

                // VIEW PAYSLIP MODAL
                function viewPayslipModal(period, num, net) {
                    var m = document.getElementById('modalViewPayslip');
                    var t = document.getElementById('payslipModalTitle');
                    var s = document.getElementById('payslipModalSub');
                    var n = document.getElementById('payslipNetDisplay');
                    if (m) {
                        if (t) t.textContent = 'Payslip — ' + period;
                        if (s) s.textContent = 'Receipt #' + num;
                        if (n) n.textContent = '₹ ' + net;
                        m.style.display = 'flex';
                    }
                }
                function closeViewPayslipModal() {
                    var m = document.getElementById('modalViewPayslip');
                    if (m) m.style.display = 'none';
                }

                // REPORT DETAIL MODAL
                function openReportDetailModal(title) {
                    alert('Generating full ' + title + ' view for employee.');
                }

                function generateCustomEmployeeReport() {
                    var sel = document.getElementById('selReportType');
                    var reportType = sel ? sel.options[sel.selectedIndex].text : 'Selected Report';
                    alert('Custom ' + reportType + ' generated successfully for period Oct 1 - Oct 31, 2026.');
                }

                // PROFILE DROPDOWN INTERACTION AND ACCESSIBILITY
                function toggleAdminDropdown(e) {
                    if (e) e.stopPropagation();
                    var menu = document.getElementById('adminDropdownMenu');
                    var trigger = document.getElementById('adminProfileTrigger');
                    if (menu) {
                        var isExpanded = (menu.style.display === 'block');
                        menu.style.display = isExpanded ? 'none' : 'block';
                        if (trigger) trigger.setAttribute('aria-expanded', !isExpanded);
                    }
                }

                function handleProfileKeydown(e) {
                    if (e.key === 'Enter' || e.key === ' ') {
                        e.preventDefault();
                        toggleAdminDropdown(e);
                    } else if (e.key === 'Escape') {
                        var menu = document.getElementById('adminDropdownMenu');
                        var trigger = document.getElementById('adminProfileTrigger');
                        if (menu) {
                            if (menu.style.display === 'block') {
                                menu.style.display = 'none';
                                if (trigger) {
                                    trigger.setAttribute('aria-expanded', 'false');
                                    trigger.focus();
                                }
                            }
                        }
                    }
                }

                // DATE FILTER DROPDOWN AND RANGE SELECTION
                function toggleDateFilterMenu(e) {
                    if (e) e.stopPropagation();
                    var dd = document.getElementById('adminDateFilterDropdown');
                    if (dd) {
                        dd.style.display = (dd.style.display === 'block') ? 'none' : 'block';
                    }
                }

                function selectDateRange(rangeKey) {
                    var currentUrl = new URL(window.location.href);
                    currentUrl.searchParams.set('date_range', rangeKey);
                    currentUrl.searchParams.delete('start_date');
                    currentUrl.searchParams.delete('end_date');
                    window.location.href = currentUrl.toString();
                }

                function applyCustomDateRange() {
                    var s = document.getElementById('adminCustomStartDate').value;
                    var e = document.getElementById('adminCustomEndDate').value;
                    if (!s || !e) {
                        alert('Please select both start date and end date.');
                        return;
                    }
                    if (new Date(e) < new Date(s)) {
                        alert('End date cannot be earlier than start date.');
                        return;
                    }
                    var currentUrl = new URL(window.location.href);
                    currentUrl.searchParams.set('date_range', 'custom');
                    currentUrl.searchParams.set('start_date', s);
                    currentUrl.searchParams.set('end_date', e);
                    window.location.href = currentUrl.toString();
                }

                function resetDateFilter() {
                    var currentUrl = new URL(window.location.href);
                    currentUrl.searchParams.delete('date_range');
                    currentUrl.searchParams.delete('start_date');
                    currentUrl.searchParams.delete('end_date');
                    window.location.href = currentUrl.toString();
                }

                // GLOBAL SEARCH WITH DEBOUNCE AND KEYBOARD NAVIGATION
                var searchDebounceTimer = null;
                var searchSelectedIndex = -1;

                var searchInput = document.getElementById('adminGlobalSearchInp');
                var searchDropdown = document.getElementById('adminSearchResults');

                if (searchInput) {
                    if (searchDropdown) {
                        searchInput.addEventListener('input', function(e) {
                            var val = e.target.value.trim();
                            clearTimeout(searchDebounceTimer);
                            if (!val || val.length < 2) {
                                searchDropdown.style.display = 'none';
                                searchDropdown.innerHTML = '';
                                searchInput.setAttribute('aria-expanded', 'false');
                                return;
                            }

                            searchDropdown.style.display = 'block';
                            searchInput.setAttribute('aria-expanded', 'true');
                            searchDropdown.innerHTML = '
Searching...';

                            searchDebounceTimer = setTimeout(function() {
                                fetch('/helpdesk/admin/global-search', {
                                    method: 'POST',
                                    headers: { 'Content-Type': 'application/json' },
                                    body: JSON.stringify({
                                        jsonrpc: '2.0',
                                        method: 'call',
                                        params: { query: val }
                                    })
                                })
                                .then(function(r) { return r.json(); })
                                .then(function(data) {
                                    var res = data.result || {};
                                    var groups = res.results || {};
                                    var total = res.total_count || 0;

                                    if (total === 0) {
                                        searchDropdown.innerHTML = '
No results found for "' + val.replace(/"/g, '"') + '"';
                                        return;
                                    }

                                    var html = '';
                                    var types = [
                                        { key: 'tickets', label: 'Tickets' },
                                        { key: 'projects', label: 'Projects' },
                                        { key: 'employees', label: 'Employees' },
                                        { key: 'customers', label: 'Customers' }
                                    ];

                                    types.forEach(function(t) {
                                        var items = groups[t.key] || [];
                                        if (items.length > 0) {
                                            html += '
' + t.label + '' + items.length + '';
                                            items.forEach(function(it) {
                                                html += '' +
                                                    '
' +
                                                        '
' + it.title + '' +
                                                        '
' + (it.subtitle || '') + '' +
                                                    '' +
                                                    '' +
                                                '';
                                            });
                                        }
                                    });

                                    searchDropdown.innerHTML = html;
                                    searchSelectedIndex = -1;
                                })
                                .catch(function(err) {
                                    searchDropdown.innerHTML = '
Search service unavailable.';
                                });
                            }, 300);
                        });

                        searchInput.addEventListener('keydown', function(e) {
                            var items = searchDropdown.querySelectorAll('.admin-search-result-item');
                            if (e.key === 'ArrowDown') {
                                e.preventDefault();
                                if (items.length > 0) {
                                    searchSelectedIndex = (searchSelectedIndex + 1) % items.length;
                                    updateSearchSelection(items);
                                }
                            } else if (e.key === 'ArrowUp') {
                                e.preventDefault();
                                if (items.length > 0) {
                                    searchSelectedIndex = (searchSelectedIndex - 1 + items.length) % items.length;
                                    updateSearchSelection(items);
                                }
                            } else if (e.key === 'Enter') {
                                if (searchSelectedIndex >= 0) {
                                    if (items[searchSelectedIndex]) {
                                        e.preventDefault();
                                        window.location.href = items[searchSelectedIndex].getAttribute('href');
                                    }
                                }
                            } else if (e.key === 'Escape') {
                                searchDropdown.style.display = 'none';
                                searchInput.setAttribute('aria-expanded', 'false');
                            }
                        });

                        function updateSearchSelection(items) {
                            items.forEach(function(el, i) {
                                if (i === searchSelectedIndex) {
                                    el.classList.add('selected');
                                    el.scrollIntoView({ block: 'nearest' });
                                } else {
                                    el.classList.remove('selected');
                                }
                            });
                        }
                    }
                }

                // Global outside click listeners
                document.addEventListener('click', function(e) {
                    var profileMenu = document.getElementById('adminDropdownMenu');
                    var profileWrap = document.querySelector('.admin-profile-wrap');
                    if (profileMenu) {
                        if (!profileWrap || !profileWrap.contains(e.target)) {
                            profileMenu.style.display = 'none';
                            var trigger = document.getElementById('adminProfileTrigger');
                            if (trigger) trigger.setAttribute('aria-expanded', 'false');
                        }
                    }

                    var dateDropdown = document.getElementById('adminDateFilterDropdown');
                    var dateWrap = document.querySelector('.admin-date-filter-wrap');
                    if (dateDropdown) {
                        if (!dateWrap || !dateWrap.contains(e.target)) {
                            dateDropdown.style.display = 'none';
                        }
                    }

                    var searchWrap = document.getElementById('adminSearchWrap');
                    if (searchDropdown) {
                        if (!searchWrap || !searchWrap.contains(e.target)) {
                            searchDropdown.style.display = 'none';
                            if (searchInput) searchInput.setAttribute('aria-expanded', 'false');
                        }
                    }
                });

                document.addEventListener('keydown', function(e) {
                    if (e.key === 'Escape') {
                        var profileMenu = document.getElementById('adminDropdownMenu');
                        if (profileMenu) profileMenu.style.display = 'none';
                        var dateDropdown = document.getElementById('adminDateFilterDropdown');
                        if (dateDropdown) dateDropdown.style.display = 'none';
                        if (searchDropdown) searchDropdown.style.display = 'none';
                    }
                });

                // PROFILE FORM SUBMISSION
                function submitUpdateProfile(e) {
                    e.preventDefault();
                    var name = document.getElementById('profName').value.trim();
                    var email = document.getElementById('profEmail').value.trim();
                    var phone = document.getElementById('profPhone').value.trim();
                    var btn = document.getElementById('btnSaveProfile');

                    if (!name || !email) {
                        alert('Name and Email are required.');
                        return;
                    }

                    if (btn) {
                        btn.disabled = true;
                        btn.innerHTML = 'Saving...';
                    }

                    fetch('/helpdesk/admin/profile/update', {
                        method: 'POST',
                        headers: { 'Content-Type': 'application/json' },
                        body: JSON.stringify({
                            jsonrpc: '2.0',
                            method: 'call',
                            params: { name: name, email: email, phone: phone }
                        })
                    })
                    .then(function(r) { return r.json(); })
                    .then(function(data) {
                        var res = data.result || {};
                        if (res.success) {
                            alert(res.message || 'Profile updated successfully!');
                            window.location.reload();
                        } else {
                            alert(res.message || 'Failed to update profile.');
                            if (btn) {
                                btn.disabled = false;
                                btn.innerHTML = 'Save Changes';
                            }
                        }
                    })
                    .catch(function() {
                        alert('Network error while updating profile.');
                        if (btn) {
                            btn.disabled = false;
                            btn.innerHTML = 'Save Changes';
                        }
                    });
                }


                function toggleAdminDropdown(e) {
                    e.stopPropagation();
                    var menu = document.getElementById('adminDropdownMenu');
                    if (menu) {
                        menu.style.display = (menu.style.display === 'block') ? 'none' : 'block';
                    }
                }
                document.addEventListener('click', function() {
                    var menu = document.getElementById('adminDropdownMenu');
                    if (menu) menu.style.display = 'none';
                });

                // LIST / KANBAN VIEW SWITCHER (List is Default)
                function setAdminView(mode) {
                    var listEl = document.getElementById('adminCurrentListView');
                    var kanbanEl = document.getElementById('adminCurrentKanbanView');
                    var btnList = document.getElementById('btnViewList');
                    var btnKanban = document.getElementById('btnViewKanban');
                    if (!listEl || !kanbanEl) return;
                    if (mode === 'kanban') {
                        listEl.style.display = 'none';
                        kanbanEl.style.display = 'block';
                        if (btnList) btnList.classList.remove('active');
                        if (btnKanban) btnKanban.classList.add('active');
                    } else {
                        listEl.style.display = 'block';
                        kanbanEl.style.display = 'none';
                        if (btnList) btnList.classList.add('active');
                        if (btnKanban) btnKanban.classList.remove('active');
                    }
                }

                // Project Modal Handlers
                function openCreateProjectModal() {
                    var m = document.getElementById('modalCreateProject');
                    if (m) m.style.display = 'flex';
                }
                function closeCreateProjectModal() {
                    var m = document.getElementById('modalCreateProject');
                    if (m) m.style.display = 'none';
                }
                function submitCreateProject() {
                    var name = document.getElementById('mProjName').value.trim();
                    if (!name) { alert('Please enter project name.'); return; }
                    var user_id = document.getElementById('mProjUser').value;
                    var partner_id = document.getElementById('mProjPartner').value;
                    var privacy = document.getElementById('mProjPrivacy').value;
                    var desc = document.getElementById('mProjDesc').value.trim();

                    fetch('/helpdesk/admin/project/create', {
                        method: 'POST',
                        headers: { 'Content-Type': 'application/json' },
                        body: JSON.stringify({
                            jsonrpc: '2.0', method: 'call',
                            params: { name: name, user_id: user_id, partner_id: partner_id, privacy_visibility: privacy, description: desc }
                        })
                    })
                    .then(function(r) { return r.json(); })
                    .then(function(data) {
                        var res = data.result || {};
                        if (res.success) {
                            closeCreateProjectModal();
                            window.location.reload();
                        } else {
                            alert(res.message || 'Failed to create project.');
                        }
                    })
                    .catch(function() { alert('Network error while saving project.'); });
                }

                // Employee Modal Handlers
                function openCreateEmployeeModal() {
                    var m = document.getElementById('modalCreateEmployee');
                    if (m) m.style.display = 'flex';
                }
                function closeCreateEmployeeModal() {
                    var m = document.getElementById('modalCreateEmployee');
                    if (m) m.style.display = 'none';
                }
                function submitCreateEmployee() {
                    var name = document.getElementById('mEmpName').value.trim();
                    if (!name) { alert('Please enter employee name.'); return; }
                    var email = document.getElementById('mEmpEmail').value.trim();
                    var phone = document.getElementById('mEmpPhone').value.trim();
                    var dept = document.getElementById('mEmpDept').value;
                    var job = document.getElementById('mEmpJob').value.trim();

                    fetch('/helpdesk/admin/employee/create', {
                        method: 'POST',
                        headers: { 'Content-Type': 'application/json' },
                        body: JSON.stringify({
                            jsonrpc: '2.0', method: 'call',
                            params: { name: name, work_email: email, work_phone: phone, department_id: dept, job_title: job }
                        })
                    })
                    .then(function(r) { return r.json(); })
                    .then(function(data) {
                        var res = data.result || {};
                        if (res.success) {
                            closeCreateEmployeeModal();
                            window.location.reload();
                        } else {
                            alert(res.message || 'Failed to create employee.');
                        }
                    })
                    .catch(function() { alert('Network error while saving employee.'); });
                }

